  @doc """
  Builds a refusal for `code`, filling `class` and `broken_term` from the closed table.

  A nil or empty `message` defaults to the code's meaning (`doc_of/1`). Raises
  `ArgumentError` for a code outside the closed table.

      iex> refusal = AshGraphLaw.Refusal.new(:not_admitted, "custom", %{"k" => 1})
      iex> {refusal.message, refusal.details}
      {"custom", %{"k" => 1}}

      iex> AshGraphLaw.Refusal.new(:not_admitted).message == AshGraphLaw.Refusal.doc_of(:not_admitted)
      true
  """
  @spec new(code(), String.t() | nil, map()) :: t()
  def new(code, message \\ nil, details \\ %{}) when is_map(details) do
    %__MODULE__{
      code: code,
      class: class_of(code),
      broken_term: broken_term_of(code),
      message: if(is_binary(message) and message != "", do: message, else: doc_of(code)),
      details: details
    }
  end

